def _public_ip(self) -> str | None:
    import urllib.request

    urls = (
        "https://api.ipify.org",
        "https://ifconfig.me/ip",
    )
    for url in urls:
        try:
            with urllib.request.urlopen(url, timeout=4) as response:
                text = response.read().decode("utf-8").strip()
            if text and " " not in text and len(text) < 48:
                return text
        except OSError:
            continue
    return None
